class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        from collections import defaultdict
        counts = defaultdict(int)
        curr_sum = 0
        max_sum = 0
        for i in range(k):
            counts[nums[i]] += 1
            curr_sum += nums[i]
        if len(counts) == k:
            max_sum = curr_sum
        for i in range(k, len(nums)):
            in_val, out_val = nums[i], nums[i - k]
            counts[in_val] += 1
            curr_sum += in_val
            counts[out_val] -= 1
            if counts[out_val] == 0:
                del counts[out_val]
            curr_sum -= out_val
            if len(counts) == k:
                max_sum = max(max_sum, curr_sum)
        return max_sum

class Solution {
public:
    long long maximumSubarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> counts;
        long long curr_sum = 0, max_sum = 0;
        for (int i = 0; i < k; i++) {
            counts[nums[i]]++;
            curr_sum += nums[i];
        }
        if ((int)counts.size() == k) max_sum = curr_sum;
        for (int i = k; i < (int)nums.size(); i++) {
            int in_val = nums[i], out_val = nums[i - k];
            counts[in_val]++;
            curr_sum += in_val;
            if (--counts[out_val] == 0) counts.erase(out_val);
            curr_sum -= out_val;
            if ((int)counts.size() == k) max_sum = max(max_sum, curr_sum);
        }
        return max_sum;
    }
};

class Solution {
    public long maximumSubarraySum(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        long curr_sum = 0, max_sum = 0;
        for (int i = 0; i < k; i++) {
            counts.put(nums[i], counts.getOrDefault(nums[i], 0) + 1);
            curr_sum += nums[i];
        }
        if (counts.size() == k) max_sum = curr_sum;
        for (int i = k; i < nums.length; i++) {
            int in_val = nums[i], out_val = nums[i - k];
            counts.put(in_val, counts.getOrDefault(in_val, 0) + 1);
            curr_sum += in_val;
            int out_cnt = counts.get(out_val) - 1;
            if (out_cnt == 0) counts.remove(out_val);
            else counts.put(out_val, out_cnt);
            curr_sum -= out_val;
            if (counts.size() == k) max_sum = Math.max(max_sum, curr_sum);
        }
        return max_sum;
    }
}

var maximumSubarraySum = function(nums, k) {
    const counts = new Map();
    let curr_sum = 0, max_sum = 0;
    for (let i = 0; i < k; i++) {
        counts.set(nums[i], (counts.get(nums[i]) || 0) + 1);
        curr_sum += nums[i];
    }
    if (counts.size === k) max_sum = curr_sum;
    for (let i = k; i < nums.length; i++) {
        const in_val = nums[i], out_val = nums[i - k];
        counts.set(in_val, (counts.get(in_val) || 0) + 1);
        curr_sum += in_val;
        const out_cnt = counts.get(out_val) - 1;
        if (out_cnt === 0) counts.delete(out_val);
        else counts.set(out_val, out_cnt);
        curr_sum -= out_val;
        if (counts.size === k) max_sum = Math.max(max_sum, curr_sum);
    }
    return max_sum;
};
